INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('dalolat','dalolat','{"id":"dalolat","slug":"dalolat","name":"DALOLAT","category":"Dasturlar","status":"Taqdimot","summary":"AlifBit ekotizimidagi mustaqil raqamli loyiha.","description":"DALOLAT — AlifBit loyihalari qatoridagi raqamli mahsulot. Uning rasmiy taqdimoti, tasdiqlangan imkoniyatlari va foydalanish havolasi shu sahifada e’lon qilinadi.","purpose":"Foydali g‘oyani tushunarli, qulay raqamli mahsulotga aylantirish. Mahsulot haqida batafsil ma’lumot rasmiy taqdimotda beriladi.","features":["Mahsulot haqida ma’lumot","Rasmiy yangiliklar","Taqdimot va foydalanish yo‘riqnomasi"],"platforms":["Raqamli mahsulot"],"cover":"dalolat","url":"","published":true}',1);
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('voice','ovozdan-matnga','{"id":"voice","slug":"ovozdan-matnga","name":"Ovozdan matnga","category":"AI","status":"Taqdimot","summary":"Aytilgan fikrni yozma bilimga aylantirish g‘oyasi.","description":"Ovozli materiallar bilan ishlashni soddalashtirishga qaratilgan loyiha. Yakuniy nomi, qo‘llab-quvvatlanadigan tillar va ishlash imkoniyatlari taqdimot vaqtida aniqlashtiriladi.","purpose":"Ovozda qolgan fikrni matnga ko‘chirish orqali uni o‘qish, tahrirlash va qayta ishlashni qulaylashtirish.","features":["Ovozli materiallar bilan ishlash","Matnni tartiblash konsepsiyasi","Sodda interfeys yondashuvi"],"platforms":["Platforma aniqlashtiriladi"],"cover":"voice","url":"","published":true}',1);
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('academy','academy','{"id":"academy","slug":"academy","name":"AlifBit Academy","category":"Ta’lim","status":"Taqdimot","summary":"Bilimni amaliy ko‘nikmaga aylantiradigan ta’lim.","description":"O‘qish, tushunish va amalda sinab ko‘rishga asoslangan ta’lim yo‘nalishi. Matnli darslar, o‘quv dasturlari va ma’rifiy materiallarni bir joyga jamlashni maqsad qilamiz.","purpose":"Murakkab bilimni sodda va izchil shaklda yetkazish. Kurslar katalogi tayyor bo‘lgach shu yerda paydo bo‘ladi.","features":["Matnli darslar yondashuvi","Bosqichma-bosqich o‘quv dasturlari","Amaliy topshiriqlar konsepsiyasi"],"platforms":["Veb"],"cover":"academy","url":"","published":true}',1);
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('library','library','{"id":"library","slug":"library","name":"AlifBit Library","category":"Kitoblar","status":"Taqdimot","summary":"Yaxshi kitoblar. Yangi qarashlar. Kengroq dunyo.","description":"Kitoblar, qisqartmalar va tarjimalarni jamlashga qaratilgan bilim yo‘nalishi. Faqat tarqatish huquqi mavjud yoki ruxsat olingan materiallar nashr qilinadi.","purpose":"Mutolaani qulayroq qilish va bilim manbalarini o‘quvchiga yaqinlashtirish.","features":["Elektron kitoblar","Kitob qisqartmalari","Tarjimalar va audio materiallar"],"platforms":["Veb"],"cover":"library","url":"","published":true}',1);
